/* @lc app=leetcode id=3312 lang=kotlin */ class Solution { fun lb(a: List<Long>, v: Long): Int = generateSequence(0 to a.size) { (lo, hi) -> if (lo >= hi) null else ((lo + hi) / 2).let { m -> if (a[m] <= v) m + 1 to hi else lo to m } }.last().first fun gcdValues(nums: IntArray, queries: LongArray): IntArray = nums.max().let { mx -> IntArray(mx + 1).also { f -> nums.forEach { f[it]++ } }.let { f -> LongArray(mx + 1).also { ex -> (mx downTo 1).forEach { g -> (g..mx step g).sumOf { f[it].toLong() }.let { c -> ex[g] = c * (c - 1) / 2 - (2 * g..mx step g).sumOf { ex[it] } } } }.let { ex -> ex.runningFold(0L) { a, b -> a + b }.let { p -> queries.map { q -> lb(p, q) - 1 }.toIntArray() } } } } }